package me.eiakoji.eip.construction;

import java.time.Duration;
import java.time.Instant;
import java.util.Objects;
import java.util.Optional;
import java.util.UUID;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

public class VerifyMessageConstruction {

    public sealed interface MessageEnvelope<T> permits CommandMessage, DocumentMessage, EventMessage {
        UUID messageId();
        Instant timestamp();
        Optional<UUID> correlationId();
        Optional<String> replyTo();
        Optional<Duration> timeToLive();
        String contentType();
        T payload();

        default boolean isExpired(Instant currentInstant) {
            return timeToLive()
                    .map(ttl -> currentInstant.isAfter(timestamp().plus(ttl)))
                    .orElse(false);
        }
    }

    public record CommandMessage<T>(
            UUID messageId,
            Instant timestamp,
            Optional<UUID> correlationId,
            Optional<String> replyTo,
            Optional<Duration> timeToLive,
            String contentType,
            String commandName,
            T payload
    ) implements MessageEnvelope<T> {
        public CommandMessage {
            Objects.requireNonNull(messageId, "messageId must not be null");
            Objects.requireNonNull(timestamp, "timestamp must not be null");
            Objects.requireNonNull(commandName, "commandName must not be null");
            Objects.requireNonNull(payload, "payload must not be null");
        }

        public static <T> CommandMessage<T> of(String commandName, T payload, String replyTo, Duration ttl) {
            return new CommandMessage<>(
                    UUID.randomUUID(),
                    Instant.now(),
                    Optional.of(UUID.randomUUID()),
                    Optional.ofNullable(replyTo),
                    Optional.ofNullable(ttl),
                    "application/json",
                    commandName,
                    payload
            );
        }
    }

    public record DocumentMessage<T>(
            UUID messageId,
            Instant timestamp,
            Optional<UUID> correlationId,
            Optional<String> replyTo,
            Optional<Duration> timeToLive,
            String contentType,
            String schemaVersion,
            T payload
    ) implements MessageEnvelope<T> {
        public DocumentMessage {
            Objects.requireNonNull(messageId, "messageId must not be null");
            Objects.requireNonNull(timestamp, "timestamp must not be null");
            Objects.requireNonNull(schemaVersion, "schemaVersion must not be null");
            Objects.requireNonNull(payload, "payload must not be null");
        }

        public static <T> DocumentMessage<T> replyTo(UUID correlationId, String schemaVersion, T payload) {
            return new DocumentMessage<>(
                    UUID.randomUUID(),
                    Instant.now(),
                    Optional.of(correlationId),
                    Optional.empty(),
                    Optional.empty(),
                    "application/json",
                    schemaVersion,
                    payload
            );
        }
    }

    public record EventMessage<T>(
            UUID messageId,
            Instant timestamp,
            Optional<UUID> correlationId,
            Optional<String> replyTo,
            Optional<Duration> timeToLive,
            String contentType,
            String eventType,
            T payload
    ) implements MessageEnvelope<T> {
        public EventMessage {
            Objects.requireNonNull(messageId, "messageId must not be null");
            Objects.requireNonNull(timestamp, "timestamp must not be null");
            Objects.requireNonNull(eventType, "eventType must not be null");
            Objects.requireNonNull(payload, "payload must not be null");
        }

        public static <T> EventMessage<T> of(String eventType, T payload) {
            return new EventMessage<>(
                    UUID.randomUUID(),
                    Instant.now(),
                    Optional.empty(),
                    Optional.empty(),
                    Optional.empty(),
                    "application/json",
                    eventType,
                    payload
            );
        }
    }

    public record PaymentCommand(String orderId, long amountCents, String currency) {}
    public record PaymentResult(String orderId, String transactionId, String status) {}
    public record OrderPlacedEvent(String orderId, Instant placedAt, long totalCents) {}

    public static class AsyncRequestReplyGateway {
        private final ConcurrentHashMap<UUID, CompletableFuture<DocumentMessage<PaymentResult>>> pendingRequests = new ConcurrentHashMap<>();
        private final ScheduledExecutorService timeoutScheduler = Executors.newSingleThreadScheduledExecutor();

        public CompletableFuture<DocumentMessage<PaymentResult>> sendRequest(
                CommandMessage<PaymentCommand> command,
                Duration timeout
        ) {
            UUID correlationId = command.correlationId()
                    .orElseThrow(() -> new IllegalArgumentException("Request-Reply commands must contain a correlationId"));

            CompletableFuture<DocumentMessage<PaymentResult>> future = new CompletableFuture<>();
            pendingRequests.put(correlationId, future);

            timeoutScheduler.schedule(() -> {
                CompletableFuture<DocumentMessage<PaymentResult>> expired = pendingRequests.remove(correlationId);
                if (expired != null && !expired.isDone()) {
                    expired.completeExceptionally(new TimeoutException("Correlation timed out after " + timeout.toMillis() + "ms"));
                }
            }, timeout.toMillis(), TimeUnit.MILLISECONDS);

            return future;
        }

        public boolean dispatchReply(DocumentMessage<PaymentResult> reply) {
            UUID correlationId = reply.correlationId()
                    .orElseThrow(() -> new IllegalArgumentException("Reply messages must specify a correlationId"));

            CompletableFuture<DocumentMessage<PaymentResult>> pendingFuture = pendingRequests.remove(correlationId);
            if (pendingFuture == null) {
                return false;
            }

            return pendingFuture.complete(reply);
        }

        public void shutdown() {
            timeoutScheduler.shutdown();
        }
    }
}
